int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Decode the octets using the UTF-8 decoding
    while (i < bb.limit()) {
        int o = bb.get(i++);
        if (o >= 0x80) {
            // Handle multi-byte characters
            int n = 1;
            while (o >= 0x80) {
                n++;
                o <<= 1;
            }
            int c = bb.get(i++);
            for (int j = 1; j < n; j++) {
                c = (c << 6) | (bb.get(i++) & 0x3F);
            }
            sb.append((char) c);
        } else {
            // Handle single-byte characters
            sb.append((char) o);
        }
    }
    return i;
}

