private String createLogMessage(LoggingEvent event) {
    // Get the timestamp and the log level from the event
    Timestamp timestamp = new Timestamp(event.getTimeStamp());
    String logLevel = event.getLevel().toString();
    String threadName = event.getThreadName();
    String className = event.getLoggerName();
    String methodName = event.getMethodName();
    String message = event.getMessage().getFormattedMessage();
    String exception = event.getThrown() != null ? event.getThrown().toString() : null;
    // Create a log message with the format '%timestamp %-5level [%thread] %logger{36} %method{14}() - %msg %n'
    return String.format("[%s] %-5level [%s] %-36s %-14s() - %-100s", timestamp, logLevel, threadName, className, methodName, message, exception);
}

