public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    int offset = 0;
    if (path.startsWith("/")) {
        offset = 1;
    }
    int endIndex = path.length();
    while (offset < endIndex) {
        int delimiterIndex = path.indexOf("/", offset);
        if (delimiterIndex == -1) {
            delimiterIndex = endIndex;
        }
        String segment = path.substring(offset, delimiterIndex);
        if (decode) {
            segment = URLDecoder.decode(segment, StandardCharsets.UTF_8);
        }
        offset = delimiterIndex + 1;
        segments.add(new PathSegmentImpl(segment));
    }
    return segments;
}

