    }

    Map<String, E> outgoingEdges = getOutgoingEdges(sourceVertex);
    Map<String, E> incomingEdges = getIncomingEdges(sourceVertex);

    String edgePropertyKey = e.getPropertyKey();
    if (edgePropertyKey == null || edgePropertyKey.isEmpty()) {
        throw new IllegalArgumentException("The edge must have a non-empty property key");
    }

    E existingEdge = outgoingEdges.get(edgePropertyKey);
    if (existingEdge != null) {
        throw new IllegalArgumentException(
                String.format("Edge already exists in index: [%s] -> [%s]", existingEdge, e));
    }

    outgoingEdges.put(edgePropertyKey, e);
    incomingEdges.put(edgePropertyKey, e);

