private String parseToken(final char[] terminators){
	String token = "";
	if(terminators == null){
		throw new NullPointerException("The terminators array cannot be null");
	}

	for(char c : terminators){
		if(c == '\0'){
			throw new IllegalArgumentException("The terminators array cannot contain null characters");
		}
	}

	char currentChar = (char)parseCharacter();
	while(currentChar != '\0' && !isTerminator(currentChar, terminators)){
		token += currentChar;
		currentChar = (char)parseCharacter();
	}

	return token;
}

