public static String base64Decode(final String s) {
    if (s == null) {
        return null;
    }
    try {
        ByteArrayInputStream bais = new ByteArrayInputStream(s.getBytes("US-ASCII"));
        Base64InputStream bis = new Base64InputStream(bais, true);
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        int i = 0;
        while ((i = bis.read()) != -1) {
            baos.write(i);
        }
        byte[] decodedByte = baos.toByteArray();
        return new String(decodedByte);
    } catch (UnsupportedEncodingException e) {
        e.printStackTrace();
    } catch (IOException e) {
        e.printStackTrace();
    }
    return null;
}

