private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<Integer>();
    int currentLowerBound = Integer.MIN_VALUE;
    for (K key : keys) {
        int currentKeyIdx = lowerBounds.size();
        while (currentKeyIdx > 0 && key.compareTo(lowerBounds.get(currentKeyIdx - 1)) < 0) {
            currentKeyIdx--;
        }
        lowerBounds.add(currentKeyIdx, key);
        currentLowerBound = Math.max(currentLowerBound, key.compareTo(lowerBounds.get(currentKeyIdx - 1)));
    }
    return lowerBounds;
}

